import json
import os
import re

import pytest
from playwright.sync_api import Page, expect, Route

BASE_URL = os.environ['L4_E2E_BASE_URL']
USERS_URL = BASE_URL.rstrip('/') + '/admin/users'


def _error_body(status, code, message, details=None):
    return json.dumps(
        {
            'type': 'ApiRequestError',
            'status': status,
            'code': code,
            'message': message,
            'details': details or {},
        }
    )


def _route_users_api(page, mutation_body=None, mutation_status=400):
    def handler(route):
        request = route.request
        if request.resource_type == 'document':
            route.continue_()
            return
        if '/users' not in request.url:
            route.continue_()
            return
        if request.method == 'GET':
            route.fulfill(
                status=200,
                content_type='application/json',
                body=json.dumps(
                    [
                        {
                            'userId': 'u-me',
                            'name': 'Me',
                            'email': 'me@example.com',
                            'state': 'active',
                            'rolesTeams': [],
                        },
                        {
                            'userId': 'u-other',
                            'name': 'Other',
                            'email': 'other@example.com',
                            'state': 'active',
                            'rolesTeams': [],
                        },
                    ]
                ),
            )
            return
        if mutation_body is not None and request.method in {'PATCH', 'POST', 'DELETE'}:
            route.fulfill(
                status=mutation_status,
                content_type='application/json',
                body=mutation_body,
            )
            return
        route.continue_()

    page.route(re.compile(r'.*/users.*'), handler)


