import os
import re
import pytest
from playwright.sync_api import Page, expect

BASE_URL = os.environ["L4_E2E_BASE_URL"]
CHECKED_AT = "2026-10-25T09:00:00.000000Z"
CHECKED_AT_UI = "2026-10-25 09:00:00 UTC"


def _verification_status(page: Page):
    section = page.locator("section").filter(
        has=page.get_by_role("heading", name="Chain verification")
    )
    return section.get_by_role("status")


@pytest.mark.l4("C-d2fc8f38")
def test_audit_chain_verification_status(page: Page) -> None:
    queue: list = []

    def handle(route) -> None:
        if not queue:
            route.continue_()
            return
        item = queue.pop(0)
        if item == "hold":
            return
        status_code, body = item
        route.fulfill(status=status_code, json=body)

    page.route("**/*verification*", handle)

    cases = [
        {
            "tone": "checking",
            "headline": "Checking the audit chain",
            "queue": ["hold"],
            "detail_contains": [],
        },
        {
            "tone": "ok",
            "headline": "Audit chain verified",
            "queue": [(200, {"ok": True, "checked": 42, "anchorsVerified": 2, "checkedAt": CHECKED_AT})],
            "detail_contains": ["42", "2", CHECKED_AT_UI],
        },
        {
            "tone": "ok",
            "headline": "Audit chain verified",
            "queue": [(200, {"ok": True, "checked": 42, "anchorsVerified": 0, "checkedAt": CHECKED_AT})],
            "detail_contains": ["42", "0", CHECKED_AT_UI],
        },
        {
            "tone": "ok",
            "headline": "Audit chain verified",
            "queue": [(200, {"ok": True, "checked": 0, "anchorsVerified": 0, "checkedAt": CHECKED_AT})],
            "detail_contains": ["No events to check yet. Checked at 2026-10-25 09:00:00 UTC."],
        },
        {
            "tone": "broken",
            "headline": "Audit chain broken",
            "queue": [(200, {"ok": False, "firstBadSeq": "17", "reason": "hash", "checkedAt": CHECKED_AT})],
            "detail_contains": ["17", "hash"],
        },
        {
            "tone": "unavailable",
            "headline": "Verification unavailable",
            "queue": [(403, {"code": "FORBIDDEN", "message": "x", "details": {"decisionId": "d-9"}})],
            "detail_contains": ["d-9"],
        },
    ]

    for case in cases:
        queue[:] = case["queue"]
        page.goto(BASE_URL)
        status = _verification_status(page)
        expect(status).to_be_visible()
        expect(status).to_have_class(re.compile(rf"\badmin-status--{case['tone']}\b"))
        expect(status.locator("strong")).to_have_text(case["headline"])
        for substring in case["detail_contains"]:
            expect(status).to_contain_text(substring)
